import re
import pandas as pd

def task_func(json_str):
    # Check if the input JSON string is empty
    if not json_str.strip():
        return pd.DataFrame()  # Return an empty DataFrame

    try:
        # Load JSON string into a dictionary
        data = json.loads(json_str)

        # Ensure data is a flat dictionary
        if not isinstance(data, dict):
            return pd.DataFrame()  # Return an empty DataFrame

        # Normalize the dictionary by doubling numerical values
        normalized_data = {}
        for key, value in data.items():
            if isinstance(value, int) or isinstance(value, float):
                # Double numerical values
                normalized_data[key] = value * 2
            elif isinstance(value, list):
                # Double numerical values inside lists
                normalized_data[key] = [
                    item * 2 if isinstance(item, (int, float)) else item for item in value
                ]
            elif isinstance(value, str):
                # Extract and double numerical values from strings using regex
                matches = re.findall(r"[-+]?\d*\.\d+|\d+", value)
                if matches:
                    doubled_numbers = [str(float(num) * 2) for num in matches]
                    normalized_data[key] = " ".join(doubled_numbers)
                else:
                    normalized_data[key] = value  # Keep non-numerical strings as-is
            else:
                # Leave non-numerical data types as-is
                normalized_data[key] = value

        # Create Pandas DataFrame from the dictionary
        df = pd.DataFrame([normalized_data])
        return df

    except (json.JSONDecodeError, ValueError):
        # Handle invalid JSON input or processing errors
        return pd.DataFrame()  # Return an empty DataFrame
